using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using Object=UnityEngine.Object;
public static class ArenaNativeSightPolish
{
 static Transform Gun(GameObject go){var view=go.GetComponent<SoldierWeaponView>();return view&&view.sharedFirstPersonRig?go.transform:go.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name=="SourceWeapon")??go.transform;}
 const string Folder=ArenaPolygonWeaponConversionBuilder.Root+"/Native/PDW90_UE4";
 public static object Apply()
 {
  if(EditorApplication.isPlaying)throw new Exception("Edit Mode required");var source=AssetDatabase.LoadAssetAtPath<ArenaWeaponCatalog>("Assets/Game/AnimationTests/AnimationTestCatalog.asset").entries.First(e=>e.weapon.catalogId=="animation-test-PDW90_UE4");var proof=ArenaWeaponProportionComparisonBuilder.Fitted().First(p=>p.source.weapon.catalogId==source.weapon.catalogId);var original=source.firstPersonPrefab.GetComponentsInChildren<SkinnedMeshRenderer>(true).First(s=>s.name=="SKM_PDW90").sharedMesh;
  var material=AssetDatabase.LoadAssetAtPath<Material>(Folder+"/ReflexGlass.mat");if(!material){material=new Material(Shader.Find("Universal Render Pipeline/Unlit")){name="ReflexGlass"};material.SetFloat("_Surface",1);material.SetFloat("_Blend",0);material.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);material.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);material.SetFloat("_ZWrite",0);material.SetFloat("_Cull",0);material.SetColor("_BaseColor",new Color(.42f,.34f,.16f,.045f));material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");material.renderQueue=3000;material.SetOverrideTag("RenderType","Transparent");AssetDatabase.CreateAsset(material,Folder+"/ReflexGlass.mat");}
  var corrected=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/ReflexGlassMesh.asset");int faces=0;
  if(!corrected)
  {
   var go=Object.Instantiate(source.firstPersonPrefab.gameObject);try{foreach(var a in go.GetComponentsInChildren<Animator>(true))a.enabled=false;AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/Game/AnimationTests/Clips/PDW90_UE4_Idle.anim").SampleAnimation(go,.01f);var gun=Gun(go);var skin=gun.GetComponentsInChildren<SkinnedMeshRenderer>(true).First(s=>s.sharedMesh==original);var w=original.boneWeights;var m=skin.bones.Select((b,i)=>b.localToWorldMatrix*original.bindposes[i]).ToArray();var vertices=original.vertices.Select((v,i)=>Quaternion.Euler(0,180,0)*gun.InverseTransformPoint(m[w[i].boneIndex0].MultiplyPoint3x4(v))).ToArray();var body=new List<int>();var glass=new List<int>();var triangles=original.GetTriangles(2);bool Lens(int i){var p=vertices[i];return Mathf.Abs(p.x)<.0141f&&p.y>.110f&&p.y<.141f&&p.z>.161f&&p.z<.1645f;}for(int i=0;i<triangles.Length;i+=3){var list=Lens(triangles[i])&&Lens(triangles[i+1])&&Lens(triangles[i+2])?glass:body;list.Add(triangles[i]);list.Add(triangles[i+1]);list.Add(triangles[i+2]);}faces=glass.Count/3;if(faces<4||faces>40)throw new Exception("Unexpected lens selection: "+faces);corrected=Object.Instantiate(original);corrected.name="ReflexGlassMesh";corrected.subMeshCount=original.subMeshCount+1;corrected.SetTriangles(body,2);corrected.SetTriangles(glass,original.subMeshCount);AssetDatabase.CreateAsset(corrected,Folder+"/ReflexGlassMesh.asset");}finally{Object.DestroyImmediate(go);}
  }
  var paths=new[]{AssetDatabase.GetAssetPath(source.firstPersonPrefab),AssetDatabase.GetAssetPath(source.thirdPersonPrefab),AssetDatabase.GetAssetPath(proof.converted.firstPersonPrefab),AssetDatabase.GetAssetPath(proof.converted.thirdPersonPrefab),AssetDatabase.GetAssetPath(proof.sharedBodyWeaponPrefab?proof.sharedBodyWeaponPrefab:proof.thirdPersonProof)}.Where(path=>!string.IsNullOrEmpty(path)).Distinct();
  foreach(var path in paths){var go=PrefabUtility.LoadPrefabContents(path);try{foreach(var skin in go.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(s=>s.sharedMesh==original||s.sharedMesh==corrected)){skin.sharedMesh=corrected;skin.sharedMaterials=skin.sharedMaterials.Take(corrected.subMeshCount-1).Concat(new[]{material}).ToArray();}var gun=Gun(go);if(!gun.GetComponentsInChildren<Transform>(true).Any(t=>t.name=="BuiltInReflexDot")){var dot=GameObject.CreatePrimitive(PrimitiveType.Quad);dot.name="BuiltInReflexDot";Object.DestroyImmediate(dot.GetComponent<Collider>());dot.transform.SetParent(gun,false);dot.transform.localPosition=Quaternion.Euler(0,180,0)*new Vector3(0,.123f,.162f);dot.transform.localRotation=Quaternion.Euler(0,180,0);dot.transform.localScale=Vector3.one*.0013f;dot.GetComponent<MeshRenderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Game/Materials/Weapons/Dot_red.mat");var body=gun.GetComponentsInChildren<Transform>(true).First(t=>t.name=="Body"||t.name=="Root");dot.transform.SetParent(body,true);}PrefabUtility.SaveAsPrefabAsset(go,path);}finally{PrefabUtility.UnloadPrefabContents(go);}}
  foreach(var p in ArenaWeaponProportionComparisonBuilder.Fitted().Where(p=>p.source.weapon.catalogId.StartsWith("animation-test-"))){float distance=p.source.weapon.catalogId=="animation-test-SVD_UE4"?.38f:p.source.weapon.catalogId=="animation-test-Val_UE4"?.52f:p.source.weapon.catalogId=="animation-test-Kar98K_UE4"?.50f:0;if(distance==0)continue;p.source.weapon.builtInIronEyeDistance=p.converted.weapon.builtInIronEyeDistance=distance;EditorUtility.SetDirty(p.source.weapon);EditorUtility.SetDirty(p.converted.weapon);}
  AssetDatabase.SaveAssets();return new{lensFaces=faces,prefabs=paths.Count()};
 }
}
